class Person {
    private int age;

    Person(int age) {
        setAge(age);
    }

    public void setAge(int age) {
        if (age >= 0) this.age = age;
        else this.age = 0;
    }

    public int getAge() { return age; }
}
// Test: new Person(-5).getAge() → 0

